draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw balance scale
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // Draw left plate
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 + 20, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // Draw right plate
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 20, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // Draw weight on left plate
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 + 20 - 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();

  // Draw weight on right plate
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 20 + 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
